insert into categories (slug, name_default) select 'society','Society' where not exists (select 1 from categories where slug='society');
insert into indicators (slug, name_default, category_id, unit, definition, higher_is_better)
select v.slug, v.name, c.id, v.unit, v.def, v.hib from (values
('population-density','Population density','demographics','people per km2','Midyear population divided by land area in square kilometres.',null::boolean),
('urban-population-share','Urban population','demographics','percent of population','Share of the population living in urban areas, as defined by national statistical offices.',null::boolean),
('population-65-plus','Population aged 65 and over','demographics','percent of population','Share of the total population aged 65 or older.',null::boolean),
('population-0-14','Population aged 0 to 14','demographics','percent of population','Share of the total population aged 0 to 14.',null::boolean),
('birth-rate','Birth rate','demographics','per 1,000 people','Live births during the year per 1,000 people (crude birth rate).',null::boolean),
('death-rate','Death rate','demographics','per 1,000 people','Deaths during the year per 1,000 people (crude death rate).',null::boolean),
('net-migration','Net migration','demographics','people','Number of immigrants minus number of emigrants, including citizens and non-citizens.',null::boolean),
('land-area','Land area','geography','km2','Country area excluding inland water bodies, in square kilometres.',null::boolean),
('infant-mortality','Infant mortality rate','health','per 1,000 live births','Deaths of infants under one year old per 1,000 live births.',false::boolean),
('under5-mortality','Under-5 mortality rate','health','per 1,000 live births','Probability of dying before age five, per 1,000 live births.',false::boolean),
('maternal-mortality','Maternal mortality ratio','health','per 100,000 live births','Women who die from pregnancy-related causes per 100,000 live births (modelled estimate).',false::boolean),
('health-expenditure-gdp','Health expenditure','health','percent of gdp','Current health expenditure, public and private, as a share of GDP.',null::boolean),
('health-expenditure-per-capita','Health expenditure per person','health','usd','Current health expenditure per person, in current US dollars.',null::boolean),
('physicians-density','Physicians','health','per 1,000 people','Medical doctors per 1,000 people.',true::boolean),
('literacy-rate-adult','Adult literacy rate','education','percent of population 15+','Share of people aged 15 and over who can read and write a short simple statement about their everyday life.',true::boolean),
('school-enrollment-primary','Primary school enrollment','education','percent gross','Gross enrollment ratio in primary education; can exceed 100% because of over- and under-age pupils.',null::boolean),
('school-enrollment-tertiary','Tertiary education enrollment','education','percent gross','Gross enrollment ratio in tertiary (university-level) education.',true::boolean),
('education-expenditure-gdp','Public spending on education','education','percent of gdp','Government expenditure on education as a share of GDP.',null::boolean),
('renewable-energy-share','Renewable energy','environment','percent of final energy consumption','Share of renewable energy in total final energy consumption.',true::boolean),
('forest-area-share','Forest area','environment','percent of land area','Land under natural or planted stands of trees of at least 5 metres, as a share of land area.',null::boolean),
('electricity-access','Access to electricity','infrastructure','percent of population','Share of the population with access to electricity.',true::boolean),
('co2-emissions-total','CO2 emissions','environment','mt co2e','Total carbon dioxide emissions excluding land use, in million tonnes.',null::boolean),
('pm25-exposure','Air pollution (PM2.5)','environment','µg/m3','Mean annual population-weighted exposure to fine particulate matter (PM2.5).',false::boolean),
('exports-gdp','Exports','economy','percent of gdp','Exports of goods and services as a share of GDP.',null::boolean),
('imports-gdp','Imports','economy','percent of gdp','Imports of goods and services as a share of GDP.',null::boolean),
('trade-gdp','Trade openness','economy','percent of gdp','Sum of exports and imports of goods and services as a share of GDP.',null::boolean),
('current-account-gdp','Current account balance','economy','percent of gdp','Current account balance as a share of GDP; positive values are surpluses.',null::boolean),
('remittances-gdp','Remittances received','economy','percent of gdp','Personal remittances received from workers abroad, as a share of GDP.',null::boolean),
('agriculture-share-gdp','Agriculture','economy','percent of gdp','Value added by agriculture, forestry and fishing as a share of GDP.',null::boolean),
('industry-share-gdp','Industry','economy','percent of gdp','Value added by industry, including construction, as a share of GDP.',null::boolean),
('services-share-gdp','Services','economy','percent of gdp','Value added by services as a share of GDP.',null::boolean),
('gni-per-capita-atlas','GNI per capita (Atlas method)','economy','usd','Gross national income per person, converted with the World Bank Atlas method, in current US dollars.',true::boolean),
('extreme-poverty','Extreme poverty','development','percent of population','Share of the population living below the international poverty line ($3.00 a day, 2021 PPP).',false::boolean),
('rd-expenditure-gdp','Research and development spending','science','percent of gdp','Gross domestic expenditure on research and development as a share of GDP.',true::boolean),
('tourist-arrivals','International tourist arrivals','economy','people','Number of international overnight visitors arriving in the country.',null::boolean),
('tax-revenue-gdp','Tax revenue','public-finance','percent of gdp','Compulsory transfers to the central government for public purposes, as a share of GDP.',null::boolean),
('military-expenditure-gdp','Military expenditure','military','percent of gdp','Military expenditure as a share of GDP (SIPRI data published by the World Bank).',null::boolean),
('military-expenditure-usd','Military expenditure (US$)','military','usd','Military expenditure in current US dollars (SIPRI data published by the World Bank).',null::boolean),
('armed-forces-personnel','Armed forces personnel','military','people','Active-duty military personnel, including paramilitary forces.',null::boolean),
('labor-force-participation','Labour force participation','labour','percent of population 15+','Share of the population aged 15 and over that is economically active (ILO modelled estimate).',null::boolean),
('female-labor-participation','Female labour force participation','labour','percent of female population 15+','Share of women aged 15 and over who are economically active (ILO modelled estimate).',null::boolean),
('youth-unemployment','Youth unemployment','labour','percent of labor force 15-24','Share of the labour force aged 15 to 24 without work but available and seeking employment (ILO modelled estimate).',false::boolean),
('internet-users','Internet users','infrastructure','percent of population','Share of the population who used the internet in the last three months.',true::boolean),
('mobile-subscriptions','Mobile phone subscriptions','infrastructure','per 100 people','Mobile cellular telephone subscriptions per 100 people.',null::boolean),
('homicide-rate','Homicide rate','society','per 100,000 people','Intentional homicides per 100,000 people (UNODC data published by the World Bank).',false::boolean),
('women-in-parliament','Women in parliament','politics','percent of seats','Share of seats held by women in national parliaments (lower or single house).',null::boolean)
) v(slug,name,cat,unit,def,hib) join categories c on c.slug=v.cat
on conflict (slug) do nothing;
